# The Complete Guide to DeFi Protocols, Testing & Security Auditing

Decentralized Finance (DeFi) represents one of blockchain's most impactful applications. Building DeFi protocols requires deep understanding of financial primitives, rigorous testing, and security-first thinking.

## DeFi Protocol Fundamentals

### Token Standards

```solidity
// ERC-20: Fungible Token Standard
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract MyToken is ERC20, Ownable {
    constructor() ERC20("MyToken", "MTK") Ownable(msg.sender) {
        _mint(msg.sender, 1000000 * 10 ** decimals());
    }

    function mint(address to, uint256 amount) public onlyOwner {
        _mint(to, amount);
    }
}
```

### Automated Market Maker (AMM)

```solidity
contract SimpleAMM {
    IERC20 public tokenA;
    IERC20 public tokenB;
    uint256 public reserveA;
    uint256 public reserveB;

    uint256 public totalLiquidity;
    mapping(address => uint256) public liquidity;

    constructor(address _tokenA, address _tokenB) {
        tokenA = IERC20(_tokenA);
        tokenB = IERC20(_tokenB);
    }

    // x * y = k (Constant Product Formula)
    function getAmountOut(
        uint256 amountIn,
        uint256 reserveIn,
        uint256 reserveOut
    ) public pure returns (uint256) {
        uint256 amountInWithFee = amountIn * 997; // 0.3% fee
        uint256 numerator = amountInWithFee * reserveOut;
        uint256 denominator = (reserveIn * 1000) + amountInWithFee;
        return numerator / denominator;
    }

    function swapAForB(uint256 amountIn) external {
        uint256 amountOut = getAmountOut(amountIn, reserveA, reserveB);

        tokenA.transferFrom(msg.sender, address(this), amountIn);
        tokenB.transfer(msg.sender, amountOut);

        reserveA += amountIn;
        reserveB -= amountOut;
    }

    function addLiquidity(
        uint256 amountA,
        uint256 amountB
    ) external returns (uint256) {
        tokenA.transferFrom(msg.sender, address(this), amountA);
        tokenB.transferFrom(msg.sender, address(this), amountB);

        uint256 liquidityMinted;
        if (totalLiquidity == 0) {
            liquidityMinted = sqrt(amountA * amountB);
        } else {
            liquidityMinted = min(
                (amountA * totalLiquidity) / reserveA,
                (amountB * totalLiquidity) / reserveB
            );
        }

        liquidity[msg.sender] += liquidityMinted;
        totalLiquidity += liquidityMinted;
        reserveA += amountA;
        reserveB += amountB;

        return liquidityMinted;
    }
}
```

### Lending Protocol Basics

```solidity
contract SimpleLending {
    IERC20 public collateralToken;
    IERC20 public borrowToken;

    uint256 public constant COLLATERAL_RATIO = 150; // 150%
    uint256 public constant LIQUIDATION_THRESHOLD = 120; // 120%

    struct Position {
        uint256 collateral;
        uint256 borrowed;
        uint256 lastInterestBlock;
    }

    mapping(address => Position) public positions;

    function deposit(uint256 amount) external {
        collateralToken.transferFrom(msg.sender, address(this), amount);
        positions[msg.sender].collateral += amount;
    }

    function borrow(uint256 amount) external {
        Position storage pos = positions[msg.sender];
        uint256 maxBorrow = (pos.collateral * 100) / COLLATERAL_RATIO;
        require(pos.borrowed + amount <= maxBorrow, "Exceeds collateral ratio");

        pos.borrowed += amount;
        pos.lastInterestBlock = block.number;
        borrowToken.transfer(msg.sender, amount);
    }

    function isLiquidatable(address user) public view returns (bool) {
        Position memory pos = positions[user];
        if (pos.borrowed == 0) return false;
        uint256 ratio = (pos.collateral * 100) / pos.borrowed;
        return ratio < LIQUIDATION_THRESHOLD;
    }
}
```

## Smart Contract Testing with Hardhat

### Setup

```bash
npm init -y
npm install --save-dev hardhat @nomicfoundation/hardhat-toolbox
npx hardhat init
```

### Writing Tests

```javascript
const { expect } = require("chai");
const { ethers } = require("hardhat");
const { loadFixture } = require("@nomicfoundation/hardhat-network-helpers");

describe("SimpleAMM", function () {
  async function deployFixture() {
    const [owner, user1, user2] = await ethers.getSigners();

    const Token = await ethers.getContractFactory("MyToken");
    const tokenA = await Token.deploy("TokenA", "TKA");
    const tokenB = await Token.deploy("TokenB", "TKB");

    const AMM = await ethers.getContractFactory("SimpleAMM");
    const amm = await AMM.deploy(tokenA.target, tokenB.target);

    // Setup initial balances
    await tokenA.mint(user1.address, ethers.parseEther("10000"));
    await tokenB.mint(user1.address, ethers.parseEther("10000"));

    return { amm, tokenA, tokenB, owner, user1, user2 };
  }

  describe("Swap", function () {
    it("should swap tokenA for tokenB correctly", async function () {
      const { amm, tokenA, tokenB, user1 } = await loadFixture(deployFixture);

      // Add liquidity first
      const liqAmount = ethers.parseEther("1000");
      await tokenA.connect(user1).approve(amm.target, liqAmount);
      await tokenB.connect(user1).approve(amm.target, liqAmount);
      await amm.connect(user1).addLiquidity(liqAmount, liqAmount);

      // Perform swap
      const swapAmount = ethers.parseEther("100");
      await tokenA.connect(user1).approve(amm.target, swapAmount);

      const balanceBefore = await tokenB.balanceOf(user1.address);
      await amm.connect(user1).swapAForB(swapAmount);
      const balanceAfter = await tokenB.balanceOf(user1.address);

      expect(balanceAfter).to.be.gt(balanceBefore);
    });

    it("should apply 0.3% fee", async function () {
      const { amm, tokenA, tokenB, user1 } = await loadFixture(deployFixture);

      const liqAmount = ethers.parseEther("1000");
      await tokenA.connect(user1).approve(amm.target, liqAmount);
      await tokenB.connect(user1).approve(amm.target, liqAmount);
      await amm.connect(user1).addLiquidity(liqAmount, liqAmount);

      const swapAmount = ethers.parseEther("100");
      const expectedOut = await amm.getAmountOut(
        swapAmount, liqAmount, liqAmount
      );

      // Output should be less than input due to fees
      expect(expectedOut).to.be.lt(swapAmount);
    });
  });

  describe("Liquidity", function () {
    it("should mint liquidity tokens on first deposit", async function () {
      const { amm, tokenA, tokenB, user1 } = await loadFixture(deployFixture);

      const amount = ethers.parseEther("1000");
      await tokenA.connect(user1).approve(amm.target, amount);
      await tokenB.connect(user1).approve(amm.target, amount);

      await amm.connect(user1).addLiquidity(amount, amount);

      const userLiquidity = await amm.liquidity(user1.address);
      expect(userLiquidity).to.be.gt(0);
    });
  });
});
```

### Testing with Foundry

```solidity
// test/SimpleAMM.t.sol
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/SimpleAMM.sol";
import "../src/MyToken.sol";

contract SimpleAMMTest is Test {
    SimpleAMM public amm;
    MyToken public tokenA;
    MyToken public tokenB;
    address public user1 = address(0x1);

    function setUp() public {
        tokenA = new MyToken("TokenA", "TKA");
        tokenB = new MyToken("TokenB", "TKB");
        amm = new SimpleAMM(address(tokenA), address(tokenB));

        tokenA.mint(user1, 10000 ether);
        tokenB.mint(user1, 10000 ether);
    }

    function testSwap() public {
        vm.startPrank(user1);

        tokenA.approve(address(amm), 1000 ether);
        tokenB.approve(address(amm), 1000 ether);
        amm.addLiquidity(1000 ether, 1000 ether);

        tokenA.approve(address(amm), 100 ether);
        uint256 balBefore = tokenB.balanceOf(user1);
        amm.swapAForB(100 ether);
        uint256 balAfter = tokenB.balanceOf(user1);

        assertGt(balAfter, balBefore);
        vm.stopPrank();
    }

    // Fuzz testing
    function testFuzz_SwapOutput(uint256 amountIn) public {
        vm.assume(amountIn > 0.001 ether && amountIn < 500 ether);

        vm.startPrank(user1);
        tokenA.approve(address(amm), 1000 ether);
        tokenB.approve(address(amm), 1000 ether);
        amm.addLiquidity(1000 ether, 1000 ether);

        uint256 amountOut = amm.getAmountOut(
            amountIn, 1000 ether, 1000 ether
        );
        assertGt(amountOut, 0);
        assertLt(amountOut, amountIn); // Fee ensures output < input
        vm.stopPrank();
    }
}
```

## Security Auditing

### Common Vulnerabilities

#### 1. Reentrancy

```solidity
// VULNERABLE
function withdraw() external {
    uint256 balance = balances[msg.sender];
    (bool success, ) = msg.sender.call{value: balance}("");
    require(success);
    balances[msg.sender] = 0; // State update AFTER external call!
}

// SAFE: Checks-Effects-Interactions pattern
function withdraw() external {
    uint256 balance = balances[msg.sender];
    balances[msg.sender] = 0; // State update BEFORE external call
    (bool success, ) = msg.sender.call{value: balance}("");
    require(success);
}

// SAFE: Use ReentrancyGuard
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

function withdraw() external nonReentrant {
    uint256 balance = balances[msg.sender];
    balances[msg.sender] = 0;
    (bool success, ) = msg.sender.call{value: balance}("");
    require(success);
}
```

#### 2. Integer Overflow/Underflow

```solidity
// Solidity 0.8+ has built-in overflow checking
// But be careful with unchecked blocks:

unchecked {
    uint256 result = type(uint256).max + 1; // Wraps to 0!
}
```

#### 3. Flash Loan Attacks

```solidity
// Use time-weighted average prices (TWAP)
// Don't rely on spot prices for critical operations

// VULNERABLE: Uses spot price
function getPrice() public view returns (uint256) {
    return reserveB / reserveA; // Manipulable!
}

// SAFER: Use oracle or TWAP
function getPrice() public view returns (uint256) {
    return oracle.getTimeWeightedPrice(token, 30 minutes);
}
```

#### 4. Access Control

```solidity
// Always restrict sensitive functions
import "@openzeppelin/contracts/access/AccessControl.sol";

contract MyProtocol is AccessControl {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function emergencyPause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }
}
```

### Security Auditing Checklist

1. **Reentrancy**: Follow checks-effects-interactions
2. **Access Control**: Verify all privileged functions
3. **Integer Math**: Check for overflow/underflow
4. **Oracle Manipulation**: Use TWAP or Chainlink
5. **Front-running**: Implement slippage protection
6. **Timestamp Dependence**: Don't rely on block.timestamp for critical logic
7. **Gas Limits**: Avoid unbounded loops
8. **Upgrade Safety**: Verify proxy patterns

### Static Analysis Tools

